import{c as t,Q as s,j as i,m as a}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse(`{"title":"I tried every trick to cut my LLM token usage. Here's what works","description":"","frontmatter":{"url":"https://x.com/ellen_in_sf/status/2060824482252833074","title":"I tried every trick to cut my LLM token usage. Here's what works","author":"ellen_in_sf","archived":"2026-05-31T00:00:00.000Z","handle":"@ellen_in_sf","published":"2026-05-30T00:00:00.000Z","stats":"33 likes · 2 retweets · 59 bookmarks · 3789 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-05-30-@ellen_in_sf-833074.md","filePath":"research/tweets/2026-05-30-@ellen_in_sf-833074.md","lastUpdated":1780990164000}`),n={name:"research/tweets/2026-05-30-@ellen_in_sf-833074.md"};function o(l,e,r,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="i-tried-every-trick-to-cut-my-llm-token-usage-here-s-what-works-—-ellen-in-sf" tabindex="-1">I tried every trick to cut my LLM token usage. Here&#39;s what works — @ellen_in_sf <a class="header-anchor" href="#i-tried-every-trick-to-cut-my-llm-token-usage-here-s-what-works-—-ellen-in-sf" aria-label="Permalink to &quot;I tried every trick to cut my LLM token usage. Here&#39;s what works — @ellen_in_sf&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ellen_in_sf/status/2060824482252833074" target="_blank" rel="noreferrer">https://x.com/ellen_in_sf/status/2060824482252833074</a><strong>作者</strong>：ellen_in_sf（@ellen_in_sf） <strong>發布日期</strong>：2026-05-30 <strong>收錄日期</strong>：2026-05-31 <strong>類型</strong>：Twitter Article <strong>統計</strong>：33 likes · 2 retweets · 59 bookmarks · 3789 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>I burned through my entire Claude Code token budget quickly. Here are the 11 things I implemented. All free, most take under 3 minutes.</p><hr><h2 id="understanding-my-usage" tabindex="-1">Understanding my usage <a class="header-anchor" href="#understanding-my-usage" aria-label="Permalink to &quot;Understanding my usage&quot;">​</a></h2><p>In order to understand my usage, I typed /usage on my Claude Code terminal to see where my tokens were going, broken down by what went in, what came out, and how much of my weekly limit I&#39;d burned.</p><p>[圖 1 — 來源: My Claude Code /usage]</p><p>Then /context to see how full my session was.</p><p>[圖 2 — 來源: /context on Claude Code (source: Jiquan Ngiam)]</p><p>Try it out.. it&#39;s interesting.</p><h2 id="what-i-found" tabindex="-1">What I found <a class="header-anchor" href="#what-i-found" aria-label="Permalink to &quot;What I found&quot;">​</a></h2><p>My most expensive sessions weren&#39;t the complex ones. They were long sessions where I kept adding more without clearing out and simple PRs I was going back and forth on without a stopping condition. Most of the waste wasn&#39;t the model being inefficient. The constraint turned out to be useful. More precise questions get better answers.</p><p>Here are the 11 things I implemented.</p><p>[圖 3]</p><h2 id="what-i-implemented" tabindex="-1">What I implemented <a class="header-anchor" href="#what-i-implemented" aria-label="Permalink to &quot;What I implemented&quot;">​</a></h2><ol><li>Clean up your CLAUDE.md</li></ol><p>Open your CLAUDE.md and cut anything Claude would do anyway. Every line loads on every single request. Keep it under 200 lines.</p><p>Replace long paragraphs with short rules:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Reply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> concisely.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> No</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filler.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> No</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Great question!&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explanation.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Never</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> question</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> back</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> me.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> When</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> done,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Don&#39;t summarize what you just did.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- Use TODO comments instead of explaining inline.</span></span></code></pre></div><ol start="2"><li>Switch models with /models</li></ol><p>Type /model mid-session to switch without restarting. Most people pick one model and leave it. That&#39;s wasteful.</p><ul><li>Opus / Sonnet 4 → complex refactors, architecture, hard bugs</li><li>Sonnet → tests, simple edits, explaining code</li><li>Haiku → quick lookups, formatting, renaming, anything repetitive</li></ul><p>I was using Sonnet for everything. Haiku handles most of my daily work and costs a fraction.</p><ol start="3"><li>Write one complete prompt instead of going back and forth</li></ol><p>Stop sending: fix this bug → now refactor it → ok add tests</p><p>Write it once: &quot;Fix the bug, refactor, and add tests.&quot;</p><p>Every follow-up forces a full re-read from the top. One prompt reads context once and produces one solution.</p><ol start="4"><li>Use /compact before switching tasks</li></ol><p>/compact summarizes your session and resets it while keeping intent. Run it before every task switch, not just when things feel slow.</p><p>You can guide what it keeps: /compact focus on the backend changes</p><p>[圖 4 — 來源: summarizing with /compact]</p><p>/clear when you&#39;re done with a topic entirely. And when you&#39;re done for the day: leave a quick note on what is the session id you have left.</p><p>When you come back, run claude --resume <code>&lt;session-id&gt;</code>, Claude shows the session ID right after you exit. You pick up exactly where you were, no re-indexing, no re-explaining the codebase.</p><p>[圖 5 — 來源: note the resume from Claude Code]</p><ol start="5"><li>Add a one-liner to your system prompt</li></ol><p>Respond like you&#39;re sending a Slack message, not writing a blog post.</p><p>Or more direct: Ultra-concise mode: fewest possible words. Fragments ok.</p><p>40-60% fewer output tokens on reasoning tasks.</p><p>(There&#39;s a whole Reddit thread where people pushed this to the extreme, making Claude respond in &quot;dinosaur language&quot; to strip all padding. It works. I&#39;m not going to tell you to do it.)</p><ol start="6"><li>Turn on prompt caching</li></ol><p>If you&#39;re sending the same system prompt or reference doc on every request, add cache_control: ephemeral to those blocks. You pay ~10x less on cached tokens.</p><p>This was my single biggest cost reduction.</p><ol start="7"><li>Use CLI and skills before reaching for MCP</li></ol><p>Priority order:</p><ol><li>CLI, gh instead of GitHub MCP, aws instead of AWS MCP. Zero overhead.</li><li>Skills, load on demand, only when invoked</li><li>MC, only if nothing else works</li></ol><p>Run /mcp to see what&#39;s active. Disable anything you&#39;re not using.</p><ol start="8"><li>Install the Context-mode plugin</li></ol><p>If you rely on MCP servers, install Context-mode. It indexes MCP tool output in a sandbox instead of dumping raw JSON into your session. It claims that it can cut MCP token usage by 50-90% and runs in the background, nothing to manage. What I have seen is it cuts my token.</p><ol start="9"><li>Install mem0 as a memory layer</li></ol><p>Every session, Claude starts from zero. It re-reads your CLAUDE.md (probably outdated), walks your file tree, opens every relevant file, re-discovering things it already knew last week. You pay for that loop every time.</p><p>The difference between typing fix auth vs fix auth in src/auth.js is massive. But your CLAUDE.md won&#39;t remember where auth lives after you refactor it. It&#39;s static.</p><p>mem0 sits between you and Claude. Before Claude starts reading files, it pulls what&#39;s already known. Claude skips the discovery phase and goes straight to the work.</p><p>The tokens you save aren&#39;t from shorter prompts. They&#39;re from not paying to re-learn the same codebase every session.</p><p>Type this in terminal to install.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mem0ai/mem0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mem0@mem0-plugins</span></span></code></pre></div><blockquote><p>Context-mode vs mem0, quick distinction: Context-mode = less noise per session (compresses what MCP tools dump into your context). mem0 = no amnesia between sessions (remembers your codebase so Claude doesn&#39;t start from zero every time). They work well together.</p></blockquote><ol start="10"><li>Use images instead of describing the problem</li></ol><p>Claude Code accepts images, just drag and drop them into the CLI. A picture is worth a thousand words / tokens. Instead of writing three paragraphs explaining what&#39;s broken in your UI, drop a screenshot.</p><p>This is especially useful for frontend bugs and layout issues. Less explaining, faster fixes. 11. Run a local model when you hit the limit</p><p>When you run out mid-week, point Claude Code at a local model. Free, no API key needed.</p><p>I use LM Studio:</p><ol><li>Download at lmstudio.ai</li><li>Search Qwen3-Coder and download model that you prefer.</li></ol><p>I am running it on Mac M5 48GB RAM (Apple Silicon): Qwen3-Coder-30B-A3B-Instruct MLX 4bit. If you are on a computer with 16GB RAM, you can use Qwen3-Coder-7B</p><ol><li>Go to Developer tab → Start Server (runs on localhost:1234)</li><li>Set env vars before launching Claude:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:1234/v1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">qwen3-coder-30b-a3b-instruct</span></span></code></pre></div><p>Type claude, it runs locally, no limits. Good for simpler tasks. Not a full replacement for Sonnet on hard problems.</p><hr><p>To summarize, here are the tips you can copy and save:</p><ol><li>CLAUDE.md hygiene (free, one-time)</li><li>Model routing with /models (free, immediate)</li><li>Batch tasks, stop iterating (free, habit change)</li><li>/compact + /clear between tasks (free, immediate)</li><li>Compression prompt (free, 40-60% output reduction)</li><li>Prompt caching (free, ~10x on cached tokens)</li><li>CLI and skills over MCP (free, immediate)</li><li>Context-mode plugin if you use MCP servers (free, install once)</li><li>mem0 memory layer (eliminates re-discovery loop)</li><li>Images instead of descriptions for frontend/visual tasks (free, immediate)</li><li>Local model via LM Studio (free, for when you hit the limit)</li></ol><p>Let me know what other things you do to token maxxing.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：11 個免費技巧降低 Claude Code token 消耗，核心是 CLAUDE.md 精簡、模型路由、prompt caching 與 /compact 策略。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>token 最貴的不是複雜任務，而是反覆往返的長 session 和沒有停止條件的 PR</li><li>CLAUDE.md 每行都在每次請求載入，精簡到 200 行以下是最直接的降耗</li><li>模型路由：Haiku 日常任務 → Sonnet 中級 → Opus 架構/難題</li><li>prompt caching (<code>cache_control: ephemeral</code>) 是最大單項成本削減，cached tokens 費用 ~10x 更低</li><li>mem0 消除跨 session 重新探索成本；Context-mode 壓縮 MCP tool output</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>CLAUDE.md 上限：200 行</li><li>壓縮 system prompt 效果：40-60% 減少 output tokens</li><li>Prompt caching 效益：~10x 成本降低</li><li>Context-mode：聲稱削減 50-90% MCP token 用量</li><li>mem0 安裝：<code>/plugin marketplace add mem0ai/mem0</code></li><li>LM Studio fallback：Qwen3-Coder-30B (M5 48GB) 或 Qwen3-Coder-7B (16GB RAM)</li><li>本地端點：<code>localhost:1234</code>，設定 <code>ANTHROPIC_BASE_URL</code> 即可切換</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>&quot;40-60% output token reduction&quot; 和 &quot;50-90% MCP reduction&quot; 均為作者自測，缺乏可重複基準；Context-mode 段落自相矛盾（引用官方數字後說「what I have seen is it cuts my token」，無具體數據）</li><li>壓縮 system prompt 策略會影響回應品質，文中完全未討論品質 / 效率 trade-off</li><li>mem0 插件的 session 持久記憶訴求尚待驗證；CLAUDE.md 不更新問題可能比記憶層更根本</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>11 個技巧幾乎全部可立即在 Claude Code 實施</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>多數為已知最佳實踐整合，mem0 + LM Studio fallback 組合較新</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>數字來源不明，「40-60%」「50-90%」缺乏量化基準</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>cache_control 和 LM Studio 配置較具體，整體偏操作手冊</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Claude Code 專屬，但模型路由和壓縮 prompt 概念可遷移</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.0/10</strong></td><td>9×0.3+6×0.2+5×0.2+6×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：靜態可執行的 11 條操作守則，可直接整合為 workspace token 管理規則集。</p>`,85)])])}const k=t(n,[["render",o]]);export{c as __pageData,k as default};
